using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.GameActions;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.Models.Potions;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private async Task AssertPaidCostAsync(CombatState live, Player player)
    {
        foreach (var relic in player.Relics.ToArray()) await RelicCmd.Remove(relic);
        foreach (int count in new[] { 5, 6, 7 })
        {
            await ClearPlayerPilesAsync(player);
            for (int i = 0; i < count; i++)
                await InjectCardAsync(live, player, new() { CardId = "BLOODLETTING", Pile = "Hand" });
            await InjectCardAsync(live, player, new() { CardId = "STRIKE_IRONCLAD", Pile = "Hand" });
            foreach (var potion in player.PotionSlots.ToArray()) potion?.Discard();
            InjectPotionForTest(player, "ENERGY_POTION");
            InjectPotionForTest(player, "SWIFT_POTION");
            SetEnergy(player, 3);
            await CreatureCmd.SetCurrentHp(live.Enemies.Single(), 6);
            CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
            if (!root.UsesComponentHealingCertificate)
                throw new InvalidOperationException("Expected recovery certificate: " + root.ComponentHealingRejection);
            var parent = root.ForkSimulator();
            string parentBefore = DescribeContinuationContractState(parent, root, player);
            string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
            var policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), live, false, null) with
            {
                FixedBudget = true, VerifyIncrementalSearch = true, MaxDegreeOfParallelism = 2,
                DetailedDiagnostics = false, MeasurePhasePerformance = false,
                BudgetOverrideMilliseconds = null, StopAtAcceptableBattleHpLoss = false,
                UseNoveltyPortfolio = false, PotionPolicy = SolverPotionPolicy.Smart,
                PotionStrategy = new(SolverPotionPolicy.Smart, []), RelicTargets = [],
                PrimaryIncumbents = new(),
            };
            policy = policy with { Profile = policy.Profile with
                { BeamWidth = 8, MaxExpandedNodes = 200, SoftTimeBudgetMilliseconds = 10000 } };
            var names = SolverDisplayNames.Capture(live);
            var damage = BattleDamageTracker.Observe(live);
            var proof = await Task.Run(() => CombatBeamSolver.AssertPaidCostConsumer(root, names, damage, policy, count));
            if (DescribeContinuationContractState(parent, root, player) != parentBefore
                || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
                throw new InvalidOperationException("Paid cost consumer changed parent/live/RNG.");
            var forkSeeds = Enumerable.Range(0, 16).Select(_ => parent.Fork()).ToArray();
            var results = await Task.WhenAll(forkSeeds.Select((seed, i) => Task.Run(() =>
            {
                using var isolation = SimulationNotificationIsolation.Enter();
                var child = CombatBeamSolver.PaidCostUse(seed, player, i % 2);
                return (Cost: ((SimulatedCombatState)child.State.CombatState).PotionUses
                    .Where(use => !use.Automatic).Sum(use => use.StrategicHpCost),
                    State: DescribeContinuationContractState(child, root, player));
            })));
            for (int i = 0; i < results.Length; i++)
                if (results[i].Cost != (i % 2 == 0 ? 9 : 18)
                    || results[i].State != (i % 2 == 0 ? proof.CheapState : proof.ExpensiveState))
                    throw new InvalidOperationException("Owned DOP16 cost/state/history/RNG differed.");
            using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(15));
            foreach (var pair in new[] { (Slot: 1, Sim: proof.Expensive), (Slot: 0, Sim: proof.Both) })
            {
                var potion = player.GetPotionAtSlotIndex(pair.Slot)!;
                string expected = ContinuationStamp.CapturePredicted(player, pair.Sim,
                    root.StartTurnNumber, root.Forecast, root.StartTurnNumber).StateText;
                GameAction action = await SolverController.EnqueueAndCaptureActionAsync(
                    queued => queued is UsePotionAction use && use.PotionIndex == (uint)pair.Slot
                        && ReferenceEquals(use.Player, player),
                    () => potion.EnqueueManualUse(player.Creature), deadline.Token);
                await action.CompletionTask.WaitAsync(deadline.Token);
                if (ContinuationStamp.CaptureLive(live).StateText != expected)
                    throw new InvalidOperationException("Native complete potion state/RNG differed.");
            }
            if (DescribeContinuationContractState(parent, root, player) != parentBefore)
                throw new InvalidOperationException("Native advance changed old parent.");
            using (SimulationNotificationIsolation.Enter())
            {
                var again = CombatBeamSolver.PaidCostUse(parent, player, 1);
                if (DescribeContinuationContractState(again, root, player) != proof.ExpensiveState)
                    throw new InvalidOperationException("Old root replay read advanced live values.");
            }
            _completedChecks.Add($"PaidCost:Bloodletting={count}:CompleteP0Witness={proof.WitnessHp}:ExactUses={proof.Quota}:ExtraPrunes={proof.Pruned}:InitialUnpaidKept:CheapKept:StrictEqualityKept:UnknownRecoveryKept:AutomaticExcluded:FreeRefillCostMonotone:SameIdRefillCostMonotone:48OwnedForkJobs:TwoNativePotionFullStates:OldRootAfterLiveAdvance");
        }
    }
}

internal sealed partial class CombatBeamSolver
{
    internal sealed record PaidCostProof(CombatPredictionSimulator Expensive,
        CombatPredictionSimulator Both, string CheapState, string ExpensiveState,
        int WitnessHp, int Quota, int Pruned);

    internal static CombatPredictionSimulator PaidCostUse(CombatPredictionSimulator from, Player player, int slot)
    {
        var child = from.Fork();
        var combat = (SimulatedCombatState)child.State.CombatState;
        var potion = combat.GetPotionAtSlot(player, slot)!;
        int start = child.History.Entries.Count;
        combat.BeginActionChoices((IReadOnlyList<PlanCardChoice>?)null);
        try
        {
            if (!PotionExecutionSupport.Prepare(child, combat, potion, slot, player.Creature)
                || !PotionExecutionSupport.Complete(child, combat, potion, player.Creature, null,
                    start, new ForkableSet<uint>()) || !SettleReplayActionBoundary(child, combat))
                throw new InvalidOperationException("Potion cost fixture suspended.");
        }
        finally { combat.EndActionChoices(); }
        return child;
    }

    internal static PaidCostProof AssertPaidCostConsumer(CombatRootSnapshot root, SolverDisplayNames names,
        BattleDamageSnapshot damage, SearchPolicySnapshot policy, int count)
    {
        using var isolation = SimulationNotificationIsolation.Enter();
        var witnessMember = new CombatBeamSolver(root, names, damage, policy,
            potionPolicyOverride: SolverPotionPolicy.Disabled);
        SearchNode winner = CreateOpeningSearchSeed(witnessMember.Replay([]));
        for (int i = 0; i < count; i++)
            winner = witnessMember.CostChildForTesting(winner, witnessMember.PrepareCardActions(winner)
                .First(action => action.Action.CardId == "BLOODLETTING").Action);
        winner = witnessMember.CostChildForTesting(winner, witnessMember.PrepareCardActions(winner)
            .First(action => action.Action.CardId == "STRIKE_IRONCLAD").Action);
        if (!winner.IsTerminal || winner.Snapshot.PlayerDead || winner.Snapshot.HasRisk
            || !witnessMember.TightenPrimarySearchIncumbentAtTurnLayer([winner], 0)
            || witnessMember._primaryIncumbent is not { } witnessed)
            throw new InvalidOperationException("No real complete qualified potion-free witness.");
        int quota = count == 7 ? 2 : 1;
        var baseline = new PotionFreePolicyBaseline(true, witnessed.StrategicHpDeficit,
            winner.Snapshot.PlayerHp, winner.Turn);
        var member = new CombatBeamSolver(root, names, damage, policy,
            potionPolicyOverride: SolverPotionPolicy.RequireAtLeastOne,
            potionFreePolicyBaseline: baseline, minimumPotionUses: quota, maximumPotionUses: quota,
            directSearchPurpose: DirectSearchPurpose.SmartPotionGradient);
        SearchNode Node(CombatPredictionSimulator sim) => CreateOpeningSearchSeed(member.Snapshot(sim,
            root.StartTurnNumber, actionCount: 0, shufflesCrossed: 0,
            boundary: SearchBoundaryReason.None, processedEnemyDeaths: new ForkableSet<uint>()));
        var parent = root.ForkSimulator();
        var cheap = PaidCostUse(parent, root.PlayerIdentity, 0);
        var expensive = PaidCostUse(parent, root.PlayerIdentity, 1);
        var both = PaidCostUse(expensive, root.PlayerIdentity, 0);
        if (Node(parent).Snapshot.ExplicitPotionStrategicCost != 0
            || Node(cheap).Snapshot.ExplicitPotionStrategicCost != 9
            || Node(expensive).Snapshot.ExplicitPotionStrategicCost != 18
            || Node(both).Snapshot.ExplicitPotionStrategicCost != 27)
            throw new InvalidOperationException("Recorded cost is not owned/additive.");
        if (member.ApplySmartPotionEligibilityBound([Node(parent)]).Count != 1
            || member.ApplySmartPotionEligibilityBound([Node(cheap)]).Count != 1)
            throw new InvalidOperationException("Unpaid or cheap branch incorrectly rejected.");
        int lower = StrategicHpLowerBound(Node(expensive).Snapshot, member._strategicBossHpRelief,
            member.RemainingHealingPotential(Node(expensive).Snapshot));
        if (member._smartPotionEligibilityHpCeiling is not { } old || lower > old)
            throw new InvalidOperationException("Old bound already rejects target.");
        bool pruned = member.ApplySmartPotionEligibilityBound([Node(expensive)]).Count == 0;
        if (pruned != (count == 5))
            throw new InvalidOperationException("Paid cost strict/equal threshold differed.");
        if (quota == 2 && member.ApplySmartPotionEligibilityBound([Node(both)]).Count != 0)
            throw new InvalidOperationException("Already paid 27 did not reject exact two-dose branch.");
        var unknown = expensive.Fork();
        unknown.AddGeneratedCardToCombat(PredictedCard.Create(ModelDb.Card<Alchemize>(), root.PlayerIdentity),
            PileType.Exhaust, root.PlayerIdentity, resultKind: CardGenerationResultKind.Fixed);
        if (member.ApplySmartPotionEligibilityBound([Node(unknown)]).Count != 1)
            throw new InvalidOperationException("Unknown recovery was pruned by paid cost.");
        var automatic = parent.Fork();
        var automaticCombat = (SimulatedCombatState)automatic.State.CombatState;
        automaticCombat.ConsumePotion(automaticCombat.GetPotionAtSlot(root.PlayerIdentity, 1)!);
        if (Node(automatic).Snapshot.ExplicitPotionStrategicCost != 0)
            throw new InvalidOperationException("Automatic resource counted as explicit paid cost.");
        var refill = cheap.Fork();
        ((SimulatedCombatState)refill.State.CombatState).TryProcurePotion(root.PlayerIdentity,
            ModelDb.Potion<EnergyPotion>());
        if (Node(refill).Snapshot.ExplicitPotionStrategicCost != 9
            || Node(PaidCostUse(refill, root.PlayerIdentity, 0)).Snapshot.ExplicitPotionStrategicCost != 18)
            throw new InvalidOperationException("Same-ID replenishment decreased paid cost.");
        var free = cheap.Fork();
        ((SimulatedCombatState)free.State.CombatState).TryProcurePotion(root.PlayerIdentity,
            ModelDb.Potion<SwiftPotion>(), freeFromEntropic: true);
        if (Node(PaidCostUse(free, root.PlayerIdentity, 0)).Snapshot.ExplicitPotionStrategicCost != 9)
            throw new InvalidOperationException("Free replenishment changed prior paid cost.");
        foreach (var guard in new[]
        {
            policy with { PotionPolicy = SolverPotionPolicy.Disabled },
            policy with { PotionPolicy = SolverPotionPolicy.RequireAtLeastOne },
            policy with { TheftPolicy = SolverTheftPolicy.PreserveResources },
            policy with { GrowthOpportunityTargets = GrowthOpportunityTargets.UnboundedForTesting("paid-cost") },
            policy with { RelicTargets = [new(RelicCounterId.PenNib, 2, 2, 1, 10)] },
            policy with { PotionStrategy = new(SolverPotionPolicy.Smart,
                [new(0, "ENERGY_POTION", SolverPotionDirective.Force)]) },
        })
        {
            var guarded = new CombatBeamSolver(root, names, damage, guard,
                potionPolicyOverride: SolverPotionPolicy.RequireAtLeastOne,
                potionFreePolicyBaseline: baseline, minimumPotionUses: quota, maximumPotionUses: quota,
                directSearchPurpose: DirectSearchPurpose.SmartPotionGradient);
            if (guarded._smartPotionEligibilityHpCeiling is not null)
                throw new InvalidOperationException("Paid cost ignored existing policy/goal qualification.");
        }
        return new(expensive, both,
            UnattendedTestRunner.DescribePaidCostState(cheap, root),
            UnattendedTestRunner.DescribePaidCostState(expensive, root),
            witnessed.StrategicHpDeficit, quota, member._paidCostEligibilityBranchesPruned);
    }
}

internal sealed partial class UnattendedTestRunner
{
    internal static string DescribePaidCostState(CombatPredictionSimulator sim, CombatRootSnapshot root)
        => DescribeContinuationContractState(sim, root, root.PlayerIdentity);
}

