from pathlib import Path
import json,os,subprocess,time,hashlib,re
root=Path.cwd();task=root/'.local/tool-tasks/inventory-audience-closure-20261008'
rows=json.loads((task/'pure-screen-summary.json').read_text());records=[]
for scene in ['dev-00-ironclad-elite','dev-01-silent-elite']:
 base=next(r for r in rows if r['scene']==scene and r['label']=='C1');out=task/'diagnostic'/scene;out.mkdir(parents=True,exist_ok=True)
 cmd=base['plan']['command'].copy();cmd[cmd.index('--out')+1]=str(out);cmd[cmd.index('--label')+1]='paid-cost-diagnostic-'+scene
 env=os.environ.copy();env['OFFLINE_HARNESS_COMBATSOLVER_DLL']=str(task/'build-final/CombatSolver.dll')
 for k in list(env):
  if (k.startswith('OFFLINE_HARNESS_') and k!='OFFLINE_HARNESS_COMBATSOLVER_DLL') or k.startswith('COMBATSOLVER_VERIFY') or k in ['DOTNET_PerfMapEnabled','COMPlus_PerfMapEnabled','COMBATSOLVER_MEASUREMENT_TRACE']:env.pop(k,None)
 env['OFFLINE_HARNESS_STREAM_DIAGNOSTICS']='1'
 plan={'command':cmd,'environmentOverrides':{'OFFLINE_HARNESS_STREAM_DIAGNOSTICS':'1'},'artifactSha256':base['plan']['dllSha256'],'outsidePerformanceAcceptance':True};(out/'command.json').write_text(json.dumps(plan,indent=2)+'\n')
 with (out/'launcher.log').open('w') as log:
  proc=subprocess.Popen(cmd,env=env,stdout=log,stderr=subprocess.STDOUT)
  try:code=proc.wait(timeout=120)
  except subprocess.TimeoutExpired:proc.kill();proc.wait();raise SystemExit('Diagnostic timeout, retained without retry')
 if code:raise SystemExit('Diagnostic failed, retained without retry')
 result=json.loads((out/'result.json').read_text());qualitySame=result['comparisonQuality']==base['comparisonQuality'];budgetSame=result['budget']==base['budget'];rootSame=hashlib.sha256(result['rootContinuationStamp'].encode()).hexdigest()==base['rootStampSha256']
 fields=['totalExpanded','totalTransitions','totalChoiceBranches','selectedExpanded','selectedTransitions','selectedChoiceBranches'];work={k:[base['solverMetrics'][k],result['solverMetrics'][k]] for k in fields if base['solverMetrics'][k]!=result['solverMetrics'][k]}
 events=[]
 for line in (out/'launcher.log').read_text().splitlines():
  m=re.search(r'SMART_POTION_ELIGIBILITY_BOUND ceiling=(-?\d+) pruned=(\d+) paid_cost_extra=(\d+)',line)
  if m:events.append({'ceiling':int(m[1]),'allEligibilityPruned':int(m[2]),'paidCostExtra':int(m[3])})
 assert qualitySame and budgetSame and rootSame
 record={'scene':scene,'qualitySame':qualitySame,'budgetSame':budgetSame,'rootSame':rootSame,'coreWorkDifferences':work,'events':events,'totalPaidCostExtra':sum(e['paidCostExtra'] for e in events),'resultPath':str(out/'result.json'),'resultSha256':hashlib.sha256((out/'result.json').read_bytes()).hexdigest(),'command':plan}
 records.append(record);(task/'diagnostic-summary.json').write_text(json.dumps(records,ensure_ascii=False,indent=2)+'\n');print(json.dumps(record,ensure_ascii=False),flush=True)

